import{_ as a,o as t,c as r,a3 as s}from"./chunks/framework.B5WAEDB7.js";const u=JSON.parse('{"title":"Widgets and Controllers","description":"","frontmatter":{"subtitle":"How a widget attaches to the controller that builds it, and how its handlers are named."},"headers":[],"relativePath":"guides/widgets.md","filePath":"guides/widgets.md"}'),o={name:"guides/widgets.md"};function n(i,e,l,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="widgets-and-controllers" tabindex="-1">Widgets and Controllers <a class="header-anchor" href="#widgets-and-controllers" aria-label="Permalink to &quot;Widgets and Controllers&quot;">​</a></h1><p>The widgets are <a href="https://larajax.org" target="_blank" rel="noreferrer">Larajax</a> view components. Larajax itself, with its controller, AJAX handlers, responses, flash messages and browser API, has its own documentation; this page covers only what the widgets add on top of it.</p><h2 id="built-in-the-action" tabindex="-1">Built in the action <a class="header-anchor" href="#built-in-the-action" aria-label="Permalink to &quot;Built in the action {#built-in-the-action}&quot;">​</a></h2><p>A widget built with <code>::make()</code> inside a controller action is bound to that controller. Larajax runs the page&#39;s action again before it calls an AJAX handler (see Larajax&#39;s <a href="https://larajax.org/guide/laravel-integration.html" target="_blank" rel="noreferrer">controller integration</a>), so the widget exists again when one of its own handlers is called, such as a list&#39;s paging or a form&#39;s file upload.</p><p>Build the widgets in the action, or a method it calls, on every request. A handler cannot reach a widget the action did not build, so a widget built only on the first page load stops answering its AJAX requests.</p><h2 id="handler-names" tabindex="-1">Handler names <a class="header-anchor" href="#handler-names" aria-label="Permalink to &quot;Handler names {#handler-names}&quot;">​</a></h2><p>A widget&#39;s handlers are addressed as <code>alias::onHandler</code>. The alias comes from the <code>alias</code> option, or defaults to the widget&#39;s name: <code>list</code>, <code>form</code>, <code>filter</code>, <code>toolbar</code>. The posts toolbar opens the list setup with <code>$list-&gt;getEventHandler(&#39;onLoadSetup&#39;)</code>, which returns <code>list::onLoadSetup</code>. Two widgets of the same kind on one page need their own aliases, as the <a href="/guides/lists.html#quick-create">quick post form</a> does beside the main post form.</p><p>Handlers without an alias, such as the post form&#39;s <code>onUpdate</code>, are the controller&#39;s own, and Larajax finds and calls them as its <a href="https://larajax.org/guide/ajax-handlers.html" target="_blank" rel="noreferrer">AJAX handlers</a> guide describes.</p><h2 id="widget-events" tabindex="-1">Widget events <a class="header-anchor" href="#widget-events" aria-label="Permalink to &quot;Widget events {#widget-events}&quot;">​</a></h2><p>Widgets fire local events that you can bind to from the controller with <code>bindEvent()</code>. A bound event that returns an array of partial updates adds them to the AJAX response, which lets one widget&#39;s handler refresh another widget&#39;s markup. This is how a toolbar&#39;s search refreshes its bound list: the search fires <code>search.submit</code> when a term is entered, and the binding answers with the refreshed list. A search box on its own uses the same event to update any part of the page, see <a href="/lists/search.html#standalone">a standalone search</a>.</p><p>The list fires an event for each of its extension points, such as <code>list.injectRowClass</code> for the classes of a row, see <a href="/lists/options.html#row-events">rows by record</a> and <a href="/guides/lists.html#extending-the-list">extending the list</a>. For deeper changes, subclass a widget and override its <code>event*</code> methods, listed in each guide.</p><h2 id="in-the-larajax-docs" tabindex="-1">In the Larajax docs <a class="header-anchor" href="#in-the-larajax-docs" aria-label="Permalink to &quot;In the Larajax docs&quot;">​</a></h2><p>The rest of the request belongs to Larajax:</p><ul><li><a href="https://larajax.org/guide/laravel-integration.html" target="_blank" rel="noreferrer">Controller integration</a>: extending the Larajax controller, and routes that answer both GET and POST.</li><li><a href="https://larajax.org/guide/ajax-handlers.html" target="_blank" rel="noreferrer">AJAX handlers</a> and <a href="https://larajax.org/guide/ajax-responses.html" target="_blank" rel="noreferrer">responses</a>: the <code>ajax()</code> helper&#39;s updates, redirects and validation errors.</li><li><a href="https://larajax.org/guide/flash-messages.html" target="_blank" rel="noreferrer">Flash messages</a> and <a href="https://larajax.org/guide/loading-indicators.html" target="_blank" rel="noreferrer">loading indicators</a>.</li><li><a href="https://larajax.org/controls/definition.html" target="_blank" rel="noreferrer">Hot controls</a>: <code>jax.registerControl()</code>, which the library&#39;s own controls and a <a href="/extending/custom-widgets.html">custom widget</a>&#39;s script use.</li></ul>',14)])])}const p=a(o,[["render",n]]);export{u as __pageData,p as default};
